import { memo, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { useStore } from '../../store';
import type { Floor, WalkNode, WalkEdge } from '../../types/project';
import type { Item } from '../../types/item';
import { FloorMesh } from './FloorMesh';
import { NodePoints } from './NodePoints';
import { EdgeLines } from './EdgeLines';
import { StairsMesh } from './StairsMesh';
import { ElevatorShaft } from './ElevatorShaft';
import { CameraController } from './CameraController';

const FloorGroup = memo(function FloorGroup({
  floor,
  nodes,
  edges,
  stairsItems,
  elevatorItems,
  allFloors,
}: {
  floor: Floor;
  nodes: WalkNode[];
  edges: WalkEdge[];
  stairsItems: Item[];
  elevatorItems: Item[];
  allFloors: Floor[];
}) {
  return (
    <group position={[0, floor.z, 0]}>
      <FloorMesh floor={floor} />
      <NodePoints nodes={nodes} y={0.05} />
      <EdgeLines edges={edges} nodes={nodes} y={0.05} />
      <StairsMesh items={stairsItems} floorHeight={floor.height} />
      <ElevatorShaft items={elevatorItems} floors={allFloors} />
    </group>
  );
});

export function Scene3D() {
  const project = useStore((s) => s.project);
  const cameraPreset = useStore((s) => s.cameraPreset);

  const isOrthographic = cameraPreset === 'isometric' || cameraPreset === 'top';

  const floorData = useMemo(() => {
    return project.floors.map((floor: Floor) => {
      const nodes: WalkNode[] = project.nodes.filter(
        (n: WalkNode) => n.floorId === floor.id
      );
      const edges: WalkEdge[] = project.links.filter(
        (e: WalkEdge) => e.floorId === floor.id
      );
      const items: Item[] = project.items.filter(
        (item: Item) => item.floorId === floor.id
      );
      const stairsItems = items.filter((i) => i.type === 'stairs');
      const elevatorItems = items.filter((i) => i.type === 'elevator');
      return { floor, nodes, edges, stairsItems, elevatorItems };
    });
  }, [project.floors, project.nodes, project.links, project.items]);

  return (
    <Canvas
      orthographic={isOrthographic}
      camera={
        isOrthographic
          ? { position: [15, 15, 15], zoom: 30, near: 0.1, far: 1000 }
          : { position: [10, 12, 10], fov: 60, near: 0.1, far: 1000 }
      }
      style={{ width: '100%', height: '100%' }}
    >
      <ambientLight intensity={0.6} />
      <directionalLight position={[10, 20, 10]} intensity={0.8} castShadow />
      <gridHelper args={[40, 40, '#94a3b8', '#cbd5e1']} />

      {floorData.map(({ floor, nodes, edges, stairsItems, elevatorItems }) => (
        <FloorGroup
          key={floor.id}
          floor={floor}
          nodes={nodes}
          edges={edges}
          stairsItems={stairsItems}
          elevatorItems={elevatorItems}
          allFloors={project.floors}
        />
      ))}

      <CameraController preset={cameraPreset} />
    </Canvas>
  );
}
