import type { Item, ElevatorItem, Floor } from '../../types';

interface ElevatorShaftProps {
  items: Item[];
  floors: Floor[];
}

export function ElevatorShaft({ items, floors }: ElevatorShaftProps) {
  const elevatorItems = items.filter((item): item is ElevatorItem => item.type === 'elevator');

  if (floors.length === 0) return null;

  const minZ = Math.min(...floors.map((f) => f.z));
  const maxFloor = floors.reduce((a, b) => (a.z + a.height > b.z + b.height ? a : b));
  const totalHeight = maxFloor.z + maxFloor.height - minZ;
  const centerY = minZ + totalHeight / 2;

  return (
    <>
      {elevatorItems.map((item) => {
        const anchor = item.anchor;
        if (anchor.type !== 'coordinate') return null;

        const { x, y: ay } = anchor;

        return (
          <mesh key={item.id} position={[x, centerY, ay]}>
            <boxGeometry args={[1.2, totalHeight, 1.2]} />
            <meshStandardMaterial color="#ef4444" transparent opacity={0.3} />
          </mesh>
        );
      })}
    </>
  );
}
