import { useMemo } from 'react';
import * as THREE from 'three';
import type { Floor } from '../../types';

interface FloorMeshProps {
  floor: Floor;
}

export function FloorMesh({ floor }: FloorMeshProps) {
  const geometry = useMemo(() => {
    const outline = floor.outline;
    if (outline && outline.length >= 3) {
      const shape = new THREE.Shape();
      const first = outline[0];
      if (!first) return new THREE.BoxGeometry(20, 0.1, 20);
      shape.moveTo(first.x, first.y);
      for (let i = 1; i < outline.length; i++) {
        const pt = outline[i];
        if (pt) shape.lineTo(pt.x, pt.y);
      }
      shape.closePath();

      const extrudeSettings: THREE.ExtrudeGeometryOptions = {
        depth: 0.1,
        bevelEnabled: false,
      };

      const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
      // ExtrudeGeometry extrudes along Z; rotate so slab lies flat in XZ plane (Y-up)
      geo.rotateX(-Math.PI / 2);
      return geo;
    }

    return new THREE.BoxGeometry(20, 0.1, 20);
  }, [floor.outline]);

  return (
    <mesh geometry={geometry} receiveShadow>
      <meshStandardMaterial color="#e2e8f0" transparent opacity={0.6} />
    </mesh>
  );
}
