import type { Item, StairsItem } from '../../types';

interface StairsMeshProps {
  items: Item[];
  floorHeight: number;
}

const STEP_COUNT = 6;

export function StairsMesh({ items, floorHeight }: StairsMeshProps) {
  const stairsItems = items.filter((item): item is StairsItem => item.type === 'stairs');

  return (
    <>
      {stairsItems.map((item) => {
        const anchor = item.anchor;
        if (anchor.type !== 'coordinate') return null;

        const { x, y: ay } = anchor;
        const stepHeight = floorHeight / STEP_COUNT;
        const stepDepth = 0.5;

        return (
          <group key={item.id} position={[x, 0, ay]}>
            {Array.from({ length: STEP_COUNT }, (_, i) => (
              <mesh
                key={i}
                position={[0, stepHeight * i + stepHeight / 2, stepDepth * i]}
              >
                <boxGeometry args={[1.2, stepHeight, stepDepth]} />
                <meshStandardMaterial color="#a78bfa" />
              </mesh>
            ))}
          </group>
        );
      })}
    </>
  );
}
