import type { WalkNode } from '../../types';

interface NodePointsProps {
  nodes: WalkNode[];
  y: number;
}

const KIND_COLOR: Record<WalkNode['kind'], string> = {
  path: '#3b82f6',
  door: '#f59e0b',
  poi: '#10b981',
};

export function NodePoints({ nodes, y }: NodePointsProps) {
  return (
    <>
      {nodes.map((node) => (
        <mesh key={node.id} position={[node.x, y, node.y]}>
          <sphereGeometry args={[0.15, 16, 16]} />
          <meshStandardMaterial color={KIND_COLOR[node.kind]} />
        </mesh>
      ))}
    </>
  );
}
