import { useMemo } from 'react';
import { Line } from '@react-three/drei';
import type { WalkEdge, WalkNode } from '../../types';

interface EdgeLinesProps {
  edges: WalkEdge[];
  nodes: WalkNode[];
  y: number;
}

const KIND_COLOR: Record<WalkEdge['kind'], string> = {
  walk: '#64748b',
  stairs: '#8b5cf6',
  elevator: '#ef4444',
};

export function EdgeLines({ edges, nodes, y }: EdgeLinesProps) {
  const nodeMap = useMemo(() => {
    const map = new Map<string, WalkNode>();
    for (const n of nodes) map.set(n.id, n);
    return map;
  }, [nodes]);

  return (
    <>
      {edges.map((edge) => {
        const from = nodeMap.get(edge.from);
        const to = nodeMap.get(edge.to);
        if (!from || !to) return null;

        const points: [number, number, number][] = [
          [from.x, y, from.y],
          [to.x, y, to.y],
        ];

        return (
          <Line
            key={edge.id}
            points={points}
            color={KIND_COLOR[edge.kind]}
            lineWidth={2}
          />
        );
      })}
    </>
  );
}
